pub struct Instrument {
    pub size: u32,
}

impl Instrument {
    pub fn new(size: u32) -> Instrument {
        Instrument { size }
    }
}

mod util;

use crate::util::Instrument;

pub fn build() -> Instrument {
    Instrument::new(4)
}

pub fn width(helper: &Instrument) -> u32 {
    helper.size
}

pub fn label() -> String {
    format!("Helper")
}

mod other {
    pub struct Helper;
}

#[cfg(test)]
mod tests {
    use crate::util::Instrument as H;

    #[test]
    fn builds() {
        assert_eq!(H::new(2).size, 2);
    }
}
